// Decide a que apartado pertenece un pago remoto (Bizum o transferencia).
//
// Aqui NO se calcula dinero: se leen `pendiente` y `fecha_limite` que devuelve la API.
// La IA solo ha extraer ordenante, importe y concepto; la decision es de este flujo.
//
// Se piden TODOS los apartados activos y se comparan aqui en vez de usar el parametro `q`
// de la API, porque la busqueda de la app es un LIKE: con el ordenante tal cual llega del banco
// ("CARMEN RUIZ GARCIA") no encuentra el apartado de "Carmen Ruiz".
const entrada = $('Datos del pago').first().json ?? {};
const apartados = $input.all().flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json])).filter((a) => a && a.id !== undefined);

// Normaliza: mayusculas, sin tildes y solo letras y numeros.
const normalizar = (s) => String(s ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toUpperCase()
  .replace(/[^A-Z0-9 ]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Devuelve 'exacto' | 'contenido' (fuerte) o 'inicial' | 'apellido_inicial' (debil), o null.
const fuerzaCoincidencia = (nombreCliente, ordenante) => {
  const c = normalizar(nombreCliente);
  const o = normalizar(ordenante);
  if (!c || !o) return null;
  if (c === o) return 'exacto';
  const cw = c.split(' ');
  const ow = o.split(' ');
  // "Carmen Ruiz" dentro de "Carmen Ruiz Garcia"
  if (cw.every((t) => ow.includes(t))) return 'contenido';
  // "Jorge M." dentro de "Jorge Martin"
  if (ow.every((t) => cw.some((w) => w.startsWith(t)))) return 'inicial';
  // "Romero D": apellido entero + inicial del nombre
  if (ow.length === 2 && ow[1].length === 1) {
    const apellido = cw.includes(ow[0]);
    const inicial = cw.some((w) => w !== ow[0] && w.startsWith(ow[1]));
    if (apellido && inicial) return 'apellido_inicial';
  }
  return null;
};

const ordenante = String(entrada.ordenante ?? '').trim();
const concepto = String(entrada.concepto ?? '').trim();
const hayConcepto = concepto.length > 0;

const respuesta = (motivo, apartado, candidatos, detalle) => [{
  json: {
    motivo,
    detalle: detalle ?? '',
    apartado: apartado ?? null,
    candidatos: candidatos ?? [],
    ordenante,
    concepto,
    importe: Number(entrada.importe ?? 0),
    canal: entrada.canal ?? 'bizum',
  },
}];

// 1. Si el concepto trae el numero de apartado, ese apartado manda.
const enConcepto = concepto.match(/apartado\s*#?\s*(\d+)/i);
if (enConcepto) {
  const id = Number(enConcepto[1]);
  const exacto = apartados.find((a) => a.id === id);
  if (exacto) {
    return respuesta('registrar', exacto, [exacto], 'El concepto menciona el apartado ' + id);
  }
  return respuesta('cliente_desconocido', null, [],
    'El concepto menciona el apartado ' + id + ', que no esta activo en la tienda');
}

// 2. Si no, se busca por nombre entre los apartados activos.
const fuerte = [];
const debil = [];
for (const apartado of apartados) {
  const fuerza = fuerzaCoincidencia(apartado.cliente, ordenante);
  if (fuerza === null) continue;
  if (fuerza === 'exacto' || fuerza === 'contenido') {
    fuerte.push(apartado);
  } else {
    debil.push(apartado);
  }
}

const candidatos = fuerte.length > 0 ? fuerte : debil;
const esDebil = fuerte.length === 0 && debil.length > 0;

if (candidatos.length === 0) {
  return respuesta('cliente_desconocido', null, [],
    'Ningun apartado activo corresponde a "' + ordenante + '"');
}

if (candidatos.length > 1) {
  return respuesta('apartado_ambiguo', null, candidatos,
    'Hay ' + candidatos.length + ' apartados que pueden ser: ' +
    candidatos.map((a) => '#' + a.id + ' ' + a.cliente).join(', '));
}

const elegido = candidatos[0];

// 3. Nombre debil y sin concepto: no se sabe con certeza de quien es, se pregunta a Marisa.
if (esDebil && !hayConcepto) {
  return respuesta('sin_concepto', elegido, candidatos,
    'El ordenante "' + ordenante + '" solo coincide por apellido e inicial con ' +
    elegido.cliente + ' y el aviso no trae concepto');
}

return respuesta('registrar', elegido, candidatos, 'Coincide con ' + elegido.cliente);
